/* The tables of M08 · Certificates and ID cards. */

export const certificateTypes = defineTable(
  'certificate_types',
  { module: 'M08', scope: 'org' },
  {
    ...baseColumns,
    /** `leaving`, `character`, `bonafide`, `provisional`, `fee_clearance`, `date_of_birth`, `experience`, `merit`, or a custom slug */
    key: text().notNull(),
    name: text().notNull(),
    nameUr: text(),
    issuedTo: enumText(certificateTypeIssuedToOptions).notNull(),
    requiresApproval: boolean().notNull().default(false),
    /** leaving certificates */
    requiresClearance: boolean().notNull().default(false),
    /** leaving certificates */
    oneActivePerPerson: boolean().notNull().default(false),
    numberFormat: text().notNull().default('{KEY}-{yyyy}-{0000}'),
    isSystem: boolean().notNull().default(false),
    isActive: boolean().notNull().default(true),
  },
  (t) => [uniqueIndex('certificate_types_key_uq').on(t.orgId, t.key).where(live(t))],
);

export const certificateTemplates = defineTable(
  'certificate_templates',
  { module: 'M08', scope: 'org' },
  {
    ...baseColumns,
    typeId: uuid()
      .references((): AnyPgColumn => certificateTypes.id)
      .notNull(),
    name: text().notNull(),
    language: enumText(certificateTemplateLanguages).notNull(),
    page: enumText(certificateTemplatePages).notNull().default('a4_portrait'),
    /** rich text with `{{variables}}` */
    body: text().notNull(),
    showLetterhead: boolean().notNull().default(true),
    showPhoto: boolean().notNull().default(false),
    /** ordered `{ title, name?, signatureFileId? }` */
    signatures: jsonb().notNull().default([]),
    isDefault: boolean().notNull().default(false),
    status: enumText(certificateTemplateStatuses).notNull().default('draft'),
  },
  (t) => [
    uniqueIndex('certificate_templates_default_uq')
      .on(t.typeId, t.language)
      .where(sql`${t.isDefault} and ${t.status} = 'active' and ${t.deletedAt} is null`),
  ],
);

/** A certificate requested or issued. */
export const certificates = defineTable(
  'certificates',
  {
    module: 'M08',
    scope: 'branch',
    family: 'studentId',
    familyRule: { read: true, insert: { status: 'requested' } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    typeId: uuid()
      .references((): AnyPgColumn => certificateTypes.id)
      .notNull(),
    templateId: uuid()
      .references((): AnyPgColumn => certificateTemplates.id)
      .notNull(),
    /** required when issued to a student */
    studentId: uuid().references((): AnyPgColumn => students.id),
    /** required when issued to staff */
    staffId: uuid().references((): AnyPgColumn => staff.id),
    /** optional until issued; then required */
    number: text(),
    /** "For passport application" */
    purpose: text(),
    status: enumText(certificateStatuses).notNull(),
    requestedVia: enumText(certificateRequestedViaOptions).notNull().default('staff'),
    /** the merged values, frozen at issue */
    data: jsonb().notNull().default({}),
    issuedOn: dateStr(),
    issuedBy: uuid().references((): AnyPgColumn => profiles.id),
    documentId: uuid().references((): AnyPgColumn => generatedDocuments.id),
    isDuplicateCopy: boolean().notNull().default(false),
    /** for a duplicate copy */
    originalId: uuid().references((): AnyPgColumn => certificates.id),
    collectedBy: text(),
    collectedOn: dateStr(),
    revokedReason: text(),
  },
  (t) => [
    check('certificates_number_needed', sql`${t.status} <> 'issued' or ${t.number} is not null`),
    uniqueIndex('certificates_number_uq')
      .on(t.orgId, t.number)
      .where(sql`${t.deletedAt} is null and ${t.number} is not null`),
    check('certificates_person', sql`num_nonnulls(${t.studentId}, ${t.staffId}) = 1`),
  ],
);

