export const idCards = defineTable(
  'id_cards',
  { module: 'M08', scope: 'branch', family: 'studentId' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    issuedTo: enumText(idCardIssuedToOptions).notNull(),
    /** required when student */
    studentId: uuid().references((): AnyPgColumn => students.id),
    /** required when staff */
    staffId: uuid().references((): AnyPgColumn => staff.id),
    templateId: uuid()
      .references((): AnyPgColumn => idCardTemplates.id)
      .notNull(),
    /** student cards */
    academicYearId: uuid().references((): AnyPgColumn => academicYears.id),
    cardNo: text().notNull(),
    qrTokenHash: text().notNull(),
    issuedOn: dateStr().notNull(),
    validUntil: dateStr().notNull(),
    status: enumText(idCardStatuses).notNull().default('active'),
    replacedById: uuid().references((): AnyPgColumn => idCards.id),
    batchId: uuid().references((): AnyPgColumn => idCardBatches.id),
  },
  (t) => [
    check('id_cards_valid_until_from', sql`${t.validUntil} >= ${t.issuedOn}`),
    uniqueIndex('id_cards_qr_token_hash_uq').on(t.qrTokenHash),
    uniqueIndex('id_cards_active_student_uq')
      .on(t.studentId)
      .where(sql`${t.status} = 'active' and ${t.studentId} is not null and ${t.deletedAt} is null`),
    uniqueIndex('id_cards_active_staff_uq')
      .on(t.staffId)
      .where(sql`${t.status} = 'active' and ${t.staffId} is not null and ${t.deletedAt} is null`),
    check(
      'id_cards_person',
      sql`(${t.issuedTo} = 'student' and ${t.studentId} is not null and ${t.staffId} is null) or (${t.issuedTo} = 'staff' and ${t.staffId} is not null and ${t.studentId} is null)`,
    ),
  ],
);

